/* ── Public: test a provider configuration ──────────────────────── */

export interface ProviderTestResult {
  ok: boolean;
  latencyMs: number;
  error?: string;
  /** How many models the endpoint listed, when it answered with a catalog. */
  modelCount?: number;
  models?: string[];
}

/**
 * Does this key work, and what is actually at this URL?

import { describe, expect, test } from "bun:test";
import {
  capShapeScore,
  combineJudgesAndStatic,
  scoreStaticFeatures,
  shapeCeiling,
  UNJUDGED_TARGET_FIT,
  type JudgeResult,
} from "./rubric";

/**
 * The relevance gate. Static features measure shape and never read the brief,
 * so before the gate existed a fluent piece about the wrong subject scored
 * 10/10 on pacing, vocabulary and paragraph shape and carried a flat 20% of
 * the combined grade. These tests pin the fix.
 */

const brief = {
  answers: {
    audience: "City planners weighing a transit levy",
    goal: "Argue that the levy pays for itself within a decade",
  },
};

function judges(scores: number[]): JudgeResult[] {
  return scores.map((score, i) => ({
    personaId: `p${i}`,
    score,
    rationale: "r",
    provider: "test",
  }));
}

/**
 * Fluent, well-shaped prose: varied sentence length, healthy type-token ratio,
 * balanced paragraphs. It is also entirely about the wrong subject.
 */
const WELL_SHAPED = [
  "The kitchen smelled of burnt sugar and something older, something closer to rust. Mira set the pan down. She had not expected the morning to turn.",
  "Outside, the market was already loud with the particular energy of a Saturday that intends to become something. Vendors argued over awning space, and a child dragged a bicycle wheel along the kerb without any apparent purpose beyond the sound it made against the stone, which was considerable.",
  "She thought about her grandmother's hands. Flour, always. A ring worn thin. The habit of narrating a recipe aloud to nobody, as though the room were an apprentice that might one day learn.",
  "By noon the light had shifted and the whole street took on that flat, generous quality that photographers chase and rarely catch. Mira locked the door behind her, and did not look back at the pan, which would still be there, and would still be ruined, when she returned.",
].join("\n\n");

describe("shapeCeiling", () => {
  test("is a no-op at full target fit", () => {
    expect(shapeCeiling(10)).toBe(10);
  });

  test("bites hard when the draft is off-target", () => {
    expect(shapeCeiling(0)).toBe(3);
    expect(shapeCeiling(2)).toBeCloseTo(4.4, 5);
    expect(shapeCeiling(5)).toBeCloseTo(6.5, 5);
  });

  test("is monotonic in target fit", () => {
    for (let fit = 0; fit < 10; fit++) {
      expect(shapeCeiling(fit)).toBeLessThan(shapeCeiling(fit + 1));
    }
  });

  test("clamps out-of-range input rather than producing nonsense", () => {
    expect(shapeCeiling(-5)).toBe(3);
    expect(shapeCeiling(99)).toBe(10);
  });
});

describe("capShapeScore", () => {
  test("leaves a score untouched when the draft is on-target", () => {
    const { score, capped } = capShapeScore(9.4, 10);
    expect(score).toBe(9.4);
    expect(capped).toBe(false);
  });

  test("caps a perfect shape score when relevance is low, and reports it", () => {
    const { score, capped, ceiling } = capShapeScore(10, 2);
    expect(score).toBe(4.4);
    expect(ceiling).toBe(4.4);
    expect(capped).toBe(true);
  });

  test("does not inflate a score that is already below the ceiling", () => {
    const { score, capped } = capShapeScore(2, 2);
    expect(score).toBe(2);
    expect(capped).toBe(false);
  });
});

describe("combineJudgesAndStatic — the relevance gate", () => {
  const staticScore = scoreStaticFeatures(WELL_SHAPED);

  test("the fixture really does score well on shape — the premise of the gate", () => {
    // If this stops holding, every test below would pass for the wrong
    // reason: there would be no high shape score left to cap.
    expect(staticScore.perFeature.pacing).toBeGreaterThan(7);
    expect(staticScore.perFeature.vocabulary).toBeGreaterThan(7);
  });

  test("defaults to no gating so an unjudged draft is never punished", () => {
    const gated = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
    );
    const explicit = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
      UNJUDGED_TARGET_FIT,
    );
    expect(gated.combined).toBe(explicit.combined);
    expect(gated.targetFit).toBe(10);
    expect(gated.effectiveStatic).toBeCloseTo(staticScore.total, 1);
  });

  test("off-target prose grades lower than the same prose on-target", () => {
    const onTarget = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
      10,
    );
    const offTarget = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
      1,
    );
    expect(offTarget.combined).toBeLessThan(onTarget.combined);
    expect(offTarget.effectiveStatic).toBeLessThan(offTarget.staticTotal);
  });

  /**
   * The property that matters most. An earlier version of the gate
   * redistributed the static weight onto the harshest judge, which raised the
   * grade whenever the static score sat below that judge's score — a
   * relevance gate that sometimes rewarded irrelevance. Lowering target fit
   * must never increase the grade, for any combination of judge scores.
   */
  test("lowering target fit never raises the grade", () => {
    const judgeSets = [
      [2, 2, 3, 2, 2],
      [6, 6, 6, 6, 6],
      [9, 9, 8, 9, 9],
      [9, 9, 9, 9, 2],
      [3, 8, 5, 9, 4],
    ];
    for (const set of judgeSets) {
      for (let fit = 10; fit > 0; fit--) {
        const higher = combineJudgesAndStatic(
          judges(set),
          staticScore,
          brief,
          fit,
        );
        const lower = combineJudgesAndStatic(
          judges(set),
          staticScore,
          brief,
          fit - 1,
        );
        expect(lower.combined).toBeLessThanOrEqual(higher.combined);
      }
    }
  });

  test("at zero relevance the static score is capped to the floor", () => {
    const result = combineJudgesAndStatic(
      judges([8, 8, 8, 8, 3]),
      staticScore,
      brief,
      0,
    );
    expect(result.effectiveStatic).toBeLessThanOrEqual(3);
  });

  test("a strong static score cannot rescue a draft every judge dislikes", () => {
    const result = combineJudgesAndStatic(
      judges([2, 2, 3, 2, 2]),
      staticScore,
      brief,
      2,
    );
    expect(result.combined).toBeLessThan(40);
  });

  test("explains the cap in the summary when relevance is low", () => {
    const result = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
      3,
    );
    expect(result.summary).toContain("drifts from the brief (3/10 on brief)");
    expect(result.summary).toContain("held down");
    // Short enough to sit whole under the grade in the side panel.
    expect(result.summary.length).toBeLessThanOrEqual(120);
  });

  test("says nothing about capping when the draft is on-target", () => {
    const result = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
      9,
    );
    expect(result.summary).not.toContain("drifts from the brief");
  });

  test("clamps an out-of-range target fit instead of skewing the weights", () => {
    const result = combineJudgesAndStatic(
      judges([6, 6, 6, 6, 6]),
      staticScore,
      brief,
      42,
    );
    expect(result.targetFit).toBe(10);
    expect(result.effectiveStatic).toBeCloseTo(staticScore.total, 1);
  });
});
/**
 * The rubric's words, in one place.
 *
 * Written for a writer mid-draft: the verdict first, one number only when it
 * helps, then what to do. No statistics vocabulary — "standard deviation" and
 * "type-token ratio" are how the score is computed, not how to fix a draft.
 */

/** One word for a mark, so a row reads before its number does. */
export function scoreWord(score: number, max: number): string {
  const pct = max > 0 ? score / max : 0;
  if (pct >= 0.8) return "strong";
  if (pct >= 0.6) return "solid";
  if (pct >= 0.4) return "uneven";
  return "weak";
}

/** The overall verdict, in a few words. */
export function gradeVerdict(score: number): string {
  if (score >= 80) return "A strong draft.";
  if (score >= 65) return "Getting there.";
  if (score >= 50) return "A working draft with clear gaps.";
  return "Early days — the next pass matters most.";
}

/** One concrete change for a criterion that scored low. */
export function nextMoveFor(id: string): string {
  const moves: Record<string, string> = {
    targetFit:
      "Reread who the brief is for and what it should do. Find the section that serves neither, then cut it or point it back.",
    thesis:
      "Say your main point in one sentence near the top. Then check that each section supports it.",
    evidence:
      "Pick your two shakiest claims and back each one with a source, an example or a number.",
    sufficiency:
      "Find the point you move past fastest and give it one more paragraph: an example, a consequence, or an objection answered.",
    integrity:
      "Swap claims about “always” and “everyone” for ones you can show. Cut the filler words.",
    structure:
      "Where the argument changes direction, add a break or a linking sentence. Cut a paragraph that repeats one before it.",
    pacing:
      "Break one long sentence into two or three, and join two short ones.",
    voice:
      "Rewrite your first line in the tone you want, and let it set the pitch for the rest.",
    vocabulary:
      "Swap three abstract words for concrete ones, and cut one piece of jargon per paragraph.",
    paragraph:
      "Split any paragraph longer than about six sentences, so each one does a single job.",
    engagement:
      "Give the reader a reason to keep going in the first 100 words: a stake, or a question.",
  };
  return (
    moves[id] ??
    "Make the one change that would lift this score most, then reread."
  );
}

const pct = (ratio: number) => Math.round(ratio * 100);

/** Plain feedback for the measured criteria. Each: verdict, detail, move. */
export const shapeFeedback = {
  structure(paragraphs: number, sentences: number, score: number): string {
    const count = `${paragraphs} paragraph${paragraphs === 1 ? "" : "s"}, ${sentences} sentence${sentences === 1 ? "" : "s"}.`;
    return score < 4
      ? `${count} That's too few parts to feel like a beginning, a turn and an ending.`
      : `${count} Enough parts to carry a beginning, a turn and an ending.`;
  },
  pacing(average: number, spread: number): string {
    const avg = `Your sentences average ${Math.round(average)} words`;
    if (spread < 5)
      return `${avg}, and most are about the same length. Mixing in some shorter ones will give the reader a beat.`;
    if (spread > 12)
      return `${avg}, but they swing from very short to very long. Even out the extremes.`;
    if (average > 24)
      return `${avg} — on the long side. Most readers are comfortable around 12 to 22.`;
    return `${avg}, with a healthy mix of lengths.`;
  },
  vocabulary(distinctRatio: number): string {
    const share = `About ${pct(distinctRatio)}% of your words are different words.`;
    if (distinctRatio < 0.35)
      return `${share} That's a lot of repetition — look for the words you lean on.`;
    if (distinctRatio > 0.6)
      return `${share} Very varied; check it still reads plainly.`;
    return `${share} A healthy range.`;
  },
  paragraphs(count: number, shortRatio: number, longRatio: number): string {
    const short = Math.round(shortRatio * count);
    const long = Math.round(longRatio * count);
    const mix = `${short} short and ${long} long, out of ${count} paragraph${count === 1 ? "" : "s"}.`;
    if (shortRatio > 0.5 && count >= 4)
      return `${mix} It reads in fragments; join the ones that share a point.`;
    if (longRatio > 0.3)
      return `${mix} Split the long ones where the subject changes.`;
    return `${mix} A comfortable mix.`;
  },
  /** Appended when relevance holds a measured score down. */
  capped(ceiling: number, fit: number): string {
    return `This score is held at ${ceiling}/10 or below because the draft is off brief (${fit}/10). Tidy sentences can't make up for writing about the wrong thing.`;
  },
  evidence(count: number, perThousand: number): string {
    return `${count} reference${count === 1 ? "" : "s"} found (${perThousand.toFixed(1)} per 1,000 words). This counts citations; it can't tell whether they hold up.`;
  },
  integrity(
    sweeping: number,
    filler: number,
    vague: number,
    repeated: number,
  ): string {
    return `${sweeping} sweeping claim${sweeping === 1 ? "" : "s"} with nothing behind ${sweeping === 1 ? "it" : "them"}, ${pct(filler)}% filler words, ${pct(vague)}% vague words, ${pct(repeated)}% repeated paragraphs. This is a word-pattern check, so it can miss subtle padding or flag deliberate emphasis.`;
  },
  unjudgedFit:
    "Not checked this time, so nothing is held down. Connect an AI provider in Settings to check the draft against the brief.",
  unreachableEditor:
    "This editor couldn't be reached, so this 5/10 is a placeholder, not a reading.",
};

